// Check if boxes overlap
bool overlap = true;
for (int dim = 0; dim < 3; dim++) {
    if (box1.GetBoxMaxC(dim) < box2.GetBoxMinC(dim) ||
        box1.GetBoxMinC(dim) > box2.GetBoxMaxC(dim)) {
        overlap = false;
        break;
    }
}

if (overlap) {
    return BoxRelation::Overlapped;
}

// Check if boxes are adjacent
bool adjacent = true;
for (int dim = 0; dim < 3; dim++) {
    float dist = std::max(0.0f, std::min(box1.GetBoxMaxC(dim), box2.GetBoxMaxC(dim)) -
                          std::max(box1.GetBoxMinC(dim), box2.GetBoxMinC(dim)));
    if (dist > std::numeric_limits<float>::epsilon()) {
        adjacent = false;
        break;
    }
}

if (adjacent) {
    return BoxRelation::Adjacent;
}

// If neither overlapping nor adjacent, they must be separated
return BoxRelation::Separated;

